program='''from collections import defaultdict, Counter


def _infer(grid):
    h, w = len(grid), len(grid[0])
    samples = [(r + c, grid[r][c])
               for r in range(6, h) for c in range(6, w)
               if grid[r][c] != 0]
    best = None
    for p in range(2, 13):
        counts = defaultdict(Counter)
        for phase, value in samples:
            counts[phase % p][value] += 1
        score = sum(max(votes.values()) for votes in counts.values())
        result = (score, -p, p, {phase: votes.most_common(1)[0][0]
                                for phase, votes in counts.items()})
        if best is None or result[:2] > best[:2]:
            best = result
    return best[2], best[3]


def transform(grid):
    out = [row[:] for row in grid]
    p, pattern = _infer(grid)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = pattern[(r + c) % p]
    return out
'''
